Q[5305]={n="Sweet Serenity",lv=60,rl=50,zn="Blacksmithing",st={"npc","Lilith the Lithe","Winterspring",61.3,37.1},en={"npc","Lilith the Lithe","Winterspring",61.3,37.1},ob="Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith."}
