Q[5341]={n="Barov Family Fortune",lv=60,rl=52,fa="H",zn="Scholomance",zk="d",nx={5342},st={"npc","Alexi Barov","Tirisfal Glades",83.1,71.6},en={"npc","Alexi Barov","Tirisfal Glades",83.1,71.6},ob="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task."}
Q[5342]={n="The Last Barov",lv=60,rl=52,fa="H",zn="Western Plaguelands",one={5341},st={"npc","Alexi Barov","Tirisfal Glades",83.1,71.6},en={"npc","Alexi Barov","Tirisfal Glades",83.1,71.6},ob="Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.\n\nBe warned, Weldon will probably be well protected by Alliance scum."}
Q[5343]={n="Barov Family Fortune",lv=60,rl=52,fa="A",zn="Scholomance",zk="d",nx={5344},st={"npc","Weldon Barov","Western Plaguelands",43.4,83.7},en={"npc","Weldon Barov","Western Plaguelands",43.4,83.7},ob="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task."}
Q[5344]={n="The Last Barov",lv=60,rl=52,fa="A",zn="Western Plaguelands",one={5343},st={"npc","Weldon Barov","Western Plaguelands",43.4,83.7},en={"npc","Weldon Barov","Western Plaguelands",43.4,83.7},ob="Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.\n\nBe warned, Alexi will probably be well protected by Horde filth."}
Q[5382]={n="Doctor Theolen Krastinov, the Butcher",lv=60,rl=55,zn="Scholomance",zk="d",nx={5515},st={"npc","Eva Sarkhoff","Western Plaguelands",70.2,73.7},en={"npc","Eva Sarkhoff","Western Plaguelands",70.2,73.7},ob="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete."}
Q[5384]={n="Kirtonos the Herald",lv=60,rl=55,zn="Scholomance",zk="d",one={5515},st={"npc","Eva Sarkhoff","Western Plaguelands",70.2,73.7},en={"npc","Eva Sarkhoff","Western Plaguelands",70.2,73.7},ob="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.\n\nFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff."}
Q[5461]={n="The Human, Ras Frostwhisper",lv=60,rl=57,zn="Western Plaguelands",one={5384},nx={5462},st={"npc","Magistrate Marduke","Western Plaguelands",70.6,74.1},en={"npc","Magistrate Marduke","Western Plaguelands",70.6,74.1},ob="Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke."}
