Q[5465]={n="Soulbound Keepsake",lv=60,rl=57,zn="Western Plaguelands",one={5464},nx={5466},st={"npc","Leonid Barthalomew the Revered","Eastern Plaguelands",75.9,52.0},en={"npc","Magistrate Marduke","Western Plaguelands",70.6,74.1},ob="Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake."}
Q[5466]={n="The Lich, Ras Frostwhisper",lv=60,rl=57,zn="Scholomance",zk="d",one={5465},st={"npc","Magistrate Marduke","Western Plaguelands",70.6,74.1},en={"npc","Magistrate Marduke","Western Plaguelands",70.6,74.1},ob="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."}
Q[5515]={n="Krastinov's Bag of Horrors",lv=60,rl=55,zn="Scholomance",zk="d",one={5382},nx={5384},st={"npc","Eva Sarkhoff","Western Plaguelands",70.2,73.7},en={"npc","Eva Sarkhoff","Western Plaguelands",70.2,73.7},ob="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff."}
