Q[12669]={n="So Far, So Bad",lv=75,rl=74,zn="Zul'Drak",one={12661},nx={12677},st={"npc","Stefan Vadu","Zul'Drak",14.1,73.8},en={"npc","Stefan Vadu","Zul'Drak",14.1,73.8},ob="Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you.\n\nWhile at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.",rep={{1098,250,"Knights of the Ebon Blade"}}}
