Q[12675]={n="One Last Thing",lv=77,rl=74,zn="Zul'Drak",one={12674},nx={12684},st={"npc","Quetz'lun's Spirit","Zul'Drak",75.4,58.6},en={"npc","Har'koa","Zul'Drak",60.2,57.7},ob="Deliver the Underworld Power Fragments to Har'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har'koa."}
